style.css:
@-moz-document domain("youtube.com") {
/* kitten background */
  html, body, ytd-app {
    background: transparent !important;
  }

  ytd-app {
    background-image: url("https://i.postimg.cc/MKsFtL47/image.jpg") !important;
    background-position: center center !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* transparent video cards */
  #content,
  #page-manager,
  ytd-browse,
  ytd-rich-grid-renderer,
  ytd-rich-item-renderer,
  ytd-rich-grid-media,
  ytd-video-renderer,
  ytd-rich-section-renderer,
  #dismissible,
  #details,
  #meta,
  #metadata {
    background: transparent !important;
    box-shadow: none !important;
  }

  /* black video titles and metadata */
  #video-title,
  #channel-name,
  #metadata-line,
  ytd-rich-item-renderer #text,
  ytd-video-renderer #text {
    color: #000000 !important;
    opacity: 1 !important;
  }

  /* white sidebar */
  #guide-content,
  ytd-guide-renderer,
  ytd-mini-guide-renderer {
    background: #ffffff !important;
  }

  /* remove black boxes from sidebar items */
  #guide-content *,
  ytd-guide-renderer *,
  ytd-mini-guide-renderer * {
    background-color: transparent !important;
    color: #000000 !important;
    box-shadow: none !important;
  }

  /* keep sidebar itself white */
  #guide-content,
  ytd-guide-renderer {
    background-color: #ffffff !important;
  }
}
